import * as React from 'react';
import { Fragment, Suspense } from 'react';
import * as GT from 'gt-next';
import {
  "T" as Manual, "Var" as Value,
  "Num" as Count, "Currency" as Money,
  "DateTime" as When, "RelativeTime" as Relative,
  "Branch" as Choice, "Plural" as Forms, "Derive" as Derived,
} from 'gt-next';
import * as Widgets from './widgets';
import {
  Box, Card, Dashboard, LocalChoice, LocalValue, Panel, Row, Shell,
  createNode, fetchValue, preload, record, resolveName, submit, withRenderer,
} from './widgets';
type PageProps = Record<string, any>;
type RowData = { id: string; name: string; [key: string]: unknown };

export function Page<Choice extends React.ElementType>(props: PageProps) {
      const {
  account, rows, items, count, mode, enabled, fallback, selection, data,
  options, key, context, values, prototype, slots,
} = props;
      return (<main>{(() => {
      try {
        switch (mode) {
          case 'first': { const Value = LocalValue; return <Value>Local case {[<span key="first">First {account.name}</span>, , ...items, <Choice key="last" branch={mode} one="Selected" other={fallback} />]}</Value>; }
          case 'second': return <Choice branch={mode} first={[<span key="first">First {account.name}</span>, , ...items, <Choice key="last" branch={mode} one="Selected" other={fallback} />]} other="Second fallback" />;
          default: return <p>Default case {[<span key="first">First {account.name}</span>, , ...items, <Choice key="last" branch={mode} one="Selected" other={fallback} />]}</p>;
        }
      } catch (Choice) { return <Choice>Catch content {[<span key="first">First {account.name}</span>, , ...items, <Choice key="last" branch={mode} one="Selected" other={fallback} />]}</Choice>; }
      finally { record(<span>Finished {count}</span>); }
    })()}<p>After switch {account.name}</p></main>);
    }

